CREATE TEMPORARY VIEW every_scene_data_step1_${grass_region_without_quote} as
SELECT
    user_id
     ,mapping_general
     ,if(grouping(is_ads)=1,'__ALL__',is_ads) as is_ads
     ,if(grouping(is_item_card)=1,'__ALL__',is_item_card) as is_item_card
     ,sum(imp_cnt)    as imp_cnt
     ,sum(click_cnt)  as click_cnt
     ,sum(order_cnt)  as order_cnt
     ,sum(gmv)        as gmv
     ,sum(pc2_gmv)    as pc2_gmv
     ,coalesce(sum(gmv)/sum(order_cnt),0) as gpo
FROM srdi_mart.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
WHERE grass_region IN (${grass_region}) AND local_date = ${local_date}
  and mapping_general not in ('Video','Live Streaming')
group by
    is_item_card
       ,user_id
       ,is_ads
       ,mapping_general
    GROUPING SETS ((user_id,mapping_general,is_ads,is_item_card),(user_id,mapping_general,is_item_card),(user_id,mapping_general,is_ads),(user_id,mapping_general))
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW every_scene_data_step2_${grass_region_without_quote} as
SELECT
    user_id
     ,'RCMD' as mapping_general
     ,is_ads
     ,is_item_card
     ,sum(imp_cnt)    as imp_cnt
     ,sum(click_cnt)  as click_cnt
     ,sum(order_cnt)  as order_cnt
     ,sum(gmv)        as gmv
     ,sum(pc2_gmv)    as pc2_gmv
     ,coalesce(sum(gmv)/sum(order_cnt),0) as gpo
FROM every_scene_data_step1_${grass_region_without_quote}
WHERE mapping_general in ('You May Also Like','Daily Discover','Post Purchase')
group by
    is_item_card
       ,user_id
       ,is_ads
;
--sql_divide_splitter--
CREATE TEMPORARY VIEW every_scene_data_${grass_region_without_quote} as
SELECT
     a.is_item_card
    ,a.user_id
    ,a.is_ads
    ,a.mapping_general
    ,c.exp_group_id
    ,imp_cnt
    ,click_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,a.gpo
    ,b.gpo_pct
FROM(
    SELECT *
    from every_scene_data_step1_${grass_region_without_quote}
    union ALL
    select *
    from every_scene_data_step2_${grass_region_without_quote}
    ) a
left join scene_995_threshold_${grass_region_without_quote} b on a.mapping_general=b.mapping_general and a.is_ads=b.is_ads and a.is_item_card=b.is_item_card
inner join user_exp_${grass_region_without_quote} c on a.user_id= c.user_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_civ_${grass_region_without_quote} AS
SELECT
     exp_group_id
    ,mapping_general
    ,is_ads
    ,is_item_card
    ,sum(imp_cnt) as  item_imp_pv
    ,count(distinct if(imp_cnt>0,user_id,null)) as item_imp_uv
    ,sum(click_cnt) as  item_click_pv
    ,count(distinct if(click_cnt>0,user_id,null)) as item_click_uv
    ,sum(order_cnt) as order_cnt
    ,count(distinct if(order_cnt>0,user_id,null)) as  order_uv
    ,sum(gmv) as  gmv
    ,sum(pc2_gmv) as  pc2_gmv
    ,count(distinct if(imp_cnt>0 and gpo<=gpo_pct,user_id,null)) as item_imp_uv_995
    ,sum(if(gpo<=gpo_pct,gmv,0)) as gmv_995
    ,sum(if(gpo<=gpo_pct,pc2_gmv,0)) as  pc2_gmv_995
from every_scene_data_${grass_region_without_quote}
group by
     exp_group_id
    ,is_ads
    ,is_item_card
    ,mapping_general
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_type_${grass_region_without_quote} AS
SELECT ads_id
     ,placement
     ,product_type
FROM mp_paidads.dim_advertise__reg_s0_live
WHERE grass_region in (${grass_region}) and grass_date = ${local_date} and tz_type = 'local'
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_raw_step1_${grass_region_without_quote} as
select
     user_id
    ,expenditure_amt_local as ads_revenue_local
    ,expenditure_amt_usd as ads_revenue_usd
    ,if(product_type = 'ROI2.0',1,0) as is_roi2
    ,case
         when c.traffic_type = 'Livestream' then 'Live Streaming'
         else coalesce(c.traffic_type, 'Other')
    end as common_feature
from mp_paidads.dwd_advertise_performance_di__reg_s0_live a
LEFT JOIN ads_type_${grass_region_without_quote} b
ON a.ads_id = b.ads_id
AND a.placement = b.placement
left join (
    select
        entrance
         ,max(traffic_type) as traffic_type
    from mp_paidads.dim_entry_point_mapping_v2
    group by 1
) as c on a.entrance = c.entrance
where grass_region in (${grass_region}) and grass_date=${local_date} and tz_type='local'
;
--sql_divide_splitter--

CACHE TABLE ads_raw_step2_${grass_region_without_quote} AS (
select
     user_id
    ,common_feature
    ,sum(ads_revenue_local) as ads_revenue_local
    ,sum(ads_revenue_usd) as ads_revenue_usd
    ,sum(if(is_roi2=1,ads_revenue_local,0)) as ads_revenue_local_roi2
    ,sum(if(is_roi2=1,ads_revenue_usd,0)) as ads_revenue_usd_roi2
from ads_raw_step1_${grass_region_without_quote}
group by
    user_id
   ,common_feature
)
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_${grass_region_without_quote} as
select
     user_id
    ,common_feature
    ,sum(ads_revenue_local) as ads_revenue_local
    ,sum(ads_revenue_usd) as ads_revenue_usd
    ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
    ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','You May Also Like','Daily Discover','Post Purchase','Shop')
group by
     user_id
    ,common_feature
union all
select
     user_id
    ,'S&R__ALL__' as common_feature
    ,sum(ads_revenue_local) as ads_revenue_local
    ,sum(ads_revenue_usd) as ads_revenue_usd
    ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
    ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('Search','You May Also Like','Daily Discover','Post Purchase')
group by
     user_id
union all
select
     user_id
    ,'__ALL__' as common_feature
    ,sum(ads_revenue_local) as ads_revenue_local
    ,sum(ads_revenue_usd) as ads_revenue_usd
    ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
    ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
from ads_raw_step2_${grass_region_without_quote}
group by
     user_id
union all
select
    user_id
     ,'RCMD' as common_feature
     ,sum(ads_revenue_local) as ads_revenue_local
     ,sum(ads_revenue_usd) as ads_revenue_usd
     ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
     ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
from ads_raw_step2_${grass_region_without_quote}
where common_feature in ('You May Also Like','Daily Discover','Post Purchase')
group by
    user_id
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_ads_${grass_region_without_quote} as
SELECT
     exp_group_id
    ,common_feature
    ,sum(ads_revenue_local) as ads_revenue_local
    ,sum(ads_revenue_usd) as ads_revenue_usd
    ,sum(ads_revenue_local_roi2) as ads_revenue_local_roi2
    ,sum(ads_revenue_usd_roi2) as ads_revenue_usd_roi2
FROM user_exp_${grass_region_without_quote} a
left join ads_${grass_region_without_quote} b on a.user_id=b.user_id
GROUP BY
     exp_group_id
    ,common_feature
;
