INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_exp_scene_general_upgrade_1d partition (grass_region = ${grass_region},local_date = ${local_date})
select
     is_ads
    ,is_item_card
    ,a.exp_group_id
    ,b.exp_group_type
    ,null as rule_ids
    ,b.layer_id
    ,mapping_general
    ,null as request_imp_pv
    ,null as request_imp_uv
    ,item_imp_pv
    ,item_imp_uv
    ,item_click_pv
    ,item_click_uv
    ,order_cnt
    ,order_uv
    ,null as item_imp_l7d
    ,null as item_click_l7d
    ,null as order_l7d
    ,gmv
    ,ads_revenue_local
    ,null as gmv_l7d
    ,null as order_uv_l7d
    ,null as item_imp_uv_l7d
    ,pc2_gmv
    ,null as pc2_gmv_l7d
    ,ads_revenue_usd
    ,ads_revenue_local_roi2
    ,ads_revenue_usd_roi2
    ,scene_name
    ,item_imp_uv_995
    ,null as item_imp_uv_l7d_995
    ,gmv_995
    ,null as gmv_l7d_995
    ,pc2_gmv_995
from exp_civ_${grass_region_without_quote} a
left join exp_info_${grass_region_without_quote} b on a.exp_group_id=b.exp_group_id
left join exp_ads_${grass_region_without_quote} c on a.exp_group_id=c.exp_group_id and a.mapping_general=c.common_feature and a.is_ads='__ALL__' and a.is_item_card='__ALL__'
